def add_document_types(apps, schema_editor):
    document_type = apps.get_model("core", "PropertyDocumentType")
    for slug, title in DOCUMENT_TYPES:
        document_type.objects.using(schema_editor.connection.alias).get_or_create(
            slug=slug, defaults={"title": title},
        )


